def swipe_points(width, height, direction, margin=0.2):
    cx, cy = int(width / 2), int(height / 2)
    near_x, far_x = int(width * margin), int(width * (1 - margin))
    near_y, far_y = int(height * margin), int(height * (1 - margin))
    if direction == 'up':
        return ((cx, far_y), (cx, near_y))
    if direction == 'down':
        return ((cx, near_y), (cx, far_y))
    if direction == 'left':
        return ((far_x, cy), (near_x, cy))
    if direction == 'right':
        return ((near_x, cy), (far_x, cy))
    raise ValueError(f'unknown direction {direction}')

