function swipeAction(start, end, durationMs = 500) {
  if (!(durationMs > 0)) throw new Error('duration must be positive');
  const r = Math.round;
  return {
    actions: [{
      type: 'pointer',
      id: 'finger1',
      parameters: { pointerType: 'touch' },
      actions: [
        { type: 'pointerMove', duration: 0, x: r(start.x), y: r(start.y) },
        { type: 'pointerDown', button: 0 },
        { type: 'pause', duration: 100 },
        { type: 'pointerMove', duration: durationMs, x: r(end.x), y: r(end.y) },
        { type: 'pointerUp', button: 0 },
      ],
    }],
  };
}
function elementCenter(rect) {
  return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
}
